import{_ as i,W as l,s as o,u as d,ah as c,I as t,w as s,Z as e,A as p}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const C=JSON.parse('{"title":"命令行小技巧：读取文件的不同方式 | LCTT x X-CMD","titleTemplate":false,"description":"命令行小技巧：读取文件的不同方式 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行小技巧：读取文件的不同方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行小技巧：读取文件的不同方式 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181012 Command line quick tips- Reading files different ways","title":"命令行小技巧：读取文件的不同方式","tag":"201810"},"relativePath":"201810/20181012 Command line quick tips- Reading files different ways.md","filePath":"[post].md"}'),r={name:"201810/20181012 Command line quick tips- Reading files different ways.md"};function h(u,a,g,m,f,b){const n=l("Link");return d(),o("div",null,[a[15]||(a[15]=c(`<h1 id="命令行小技巧-读取文件的不同方式" tabindex="-1">命令行小技巧：读取文件的不同方式 <a class="header-anchor" href="#命令行小技巧-读取文件的不同方式" aria-label="Permalink to 命令行小技巧：读取文件的不同方式">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/10/commandlinequicktips-816x345.jpg" alt=""></p><p>作为图形操作系统，Fedora 的使用是令人愉快的。你可以轻松地点击完成任何任务。但你可能已经看到了，在底层还有一个强大的命令行。想要在 shell 下体验，只需要在 Fedora 系统中打开你的终端应用。这篇文章是向你展示常见的命令行使用方法的系列文章之一。</p><p>在这部分，你将学习如何以不同的方式读取文件，如果你在系统中打开一个终端完成一些工作，你就有可能需要读取一两个文件。</p><h3 id="一应俱全的大餐" tabindex="-1">一应俱全的大餐 <a class="header-anchor" href="#一应俱全的大餐" aria-label="Permalink to 一应俱全的大餐">​</a></h3><p>对命令行终端的用户来说， <code>cat</code> 命令众所周知。 当你 <code>cat</code> 一个文件，你很容易的把整个文件内容展示在你的屏幕上。而真正发生在底层的是文件一次读取一行，然后一行一行写入屏幕。</p><p>假设你有一个文件，叫做 <code>myfile</code>， 这个文件每行只有一个单词。为了简单起见，每行的单词就是这行的行号，就像这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>one</span></span>
<span class="line"><span>two</span></span>
<span class="line"><span>three</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>five</span></span></code></pre></div><p>所以如果你 <code>cat</code> 这个文件，你就会看到如下输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat myfile</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>two</span></span>
<span class="line"><span>three</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>five</span></span></code></pre></div><p>并没有太惊喜，不是吗？ 但是有个有趣的转折，只要使用 <code>tac</code> 命令，你可以从后往前 <code>cat</code> 这个文件。（请注意， Fedora 对这种有争议的幽默不承担任何责任！）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ tac myfile</span></span>
<span class="line"><span>five</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>three</span></span>
<span class="line"><span>two</span></span>
<span class="line"><span>one</span></span></code></pre></div><p><code>cat</code> 命令允许你以不同的方式装饰输出，比如，你可以输出行号：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat -n myfile</span></span>
<span class="line"><span>     1 one</span></span>
<span class="line"><span>     2 two</span></span>
<span class="line"><span>     3 three</span></span>
<span class="line"><span>     4 four</span></span>
<span class="line"><span>     5 five</span></span></code></pre></div><p>还有其他选项可以显示特殊字符和其他功能。要了解更多, 请运行 <code>man cat</code> 命令， 看完之后，按 <code>q</code> 即可退出回到 shell。</p><h3 id="挑选你的食物" tabindex="-1">挑选你的食物 <a class="header-anchor" href="#挑选你的食物" aria-label="Permalink to 挑选你的食物">​</a></h3><p>通常，文件太长会无法全部显示在屏幕上，您可能希望能够像文档一样查看它。 这种情况下，可以试试 <code>less</code> 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ less myfile</span></span></code></pre></div><p>你可以用方向键，也可以用 <code>PgUp</code>/<code>PgDn</code> 来查看文件， 按 <code>q</code> 就可以退回到 shell。</p><p>实际上，还有一个 <code>more</code> 命令，其基于老式的 UNIX 系统命令。如果在退回 shell 后仍想看到该文件的内容，则可能需要使用它。而 <code>less</code> 命令则让你回到你离开 shell 之前的样子，并且清除屏幕上你看到的所有的文件内容。</p><h3 id="一点披萨或甜点" tabindex="-1">一点披萨或甜点 <a class="header-anchor" href="#一点披萨或甜点" aria-label="Permalink to 一点披萨或甜点">​</a></h3><p>有时，你所需的输出只是文件的开头。 比如，有一个非常长的文件，当你使用 <code>cat</code> 命令时，会显示这个文件所有内容，前几行的内容很容易滚动过去，导致你看不到。<code>head</code> 命令会帮你获取文件的前几行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ head -n 2 myfile</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>two</span></span></code></pre></div><p>同样，你会用 <code>tail</code> 命令来查看文件的末尾几行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ tail -n 3 myfile</span></span>
<span class="line"><span>three</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>five</span></span></code></pre></div><p>当然，这些只是在这个领域的几个简单的命令。但它们可以让你在阅读文件时容易入手。</p><hr>`,27)),t("p",null,[a[1]||(a[1]=s("via: ")),e(n,{href:"https://fedoramagazine.org/commandline-quick-tips-reading-files-different-ways/"},{default:p(()=>a[0]||(a[0]=[s("https://fedoramagazine.org/commandline-quick-tips-reading-files-different-ways/")])),_:1})]),t("p",null,[a[6]||(a[6]=s("作者：")),e(n,{href:"https://fedoramagazine.org/author/pfrields/"},{default:p(()=>a[2]||(a[2]=[s("Paul W. Frields")])),_:1}),a[7]||(a[7]=s(" 选题：")),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>a[3]||(a[3]=[s("lujun9972")])),_:1}),a[8]||(a[8]=s(" 译者：")),e(n,{href:"https://github.com/distant1219"},{default:p(()=>a[4]||(a[4]=[s("distant1219")])),_:1}),a[9]||(a[9]=s(" 校对：")),e(n,{href:"https://github.com/wxy"},{default:p(()=>a[5]||(a[5]=[s("wxy")])),_:1})]),t("p",null,[a[12]||(a[12]=s("本文由 ")),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>a[10]||(a[10]=[s("LCTT")])),_:1}),a[13]||(a[13]=s(" 原创编译，")),e(n,{href:"https://linux.cn/"},{default:p(()=>a[11]||(a[11]=[s("Linux中国")])),_:1}),a[14]||(a[14]=s(" 荣誉推出"))])])}const y=i(r,[["render",h]]);export{C as __pageData,y as default};
